#!/usr/bin/env python3
import zipfile, struct, sys

def decode_cpu_registers(cpu_blob: bytes) -> dict:
    """Decode CPU registers from a DOSBox-X 2026.05.02 (64-bit build) save-state CPU blob."""
    out = {}
    names = ['EAX','ECX','EDX','EBX','ESP','EBP','ESI','EDI']
    for i, name in enumerate(names):
        out[name] = struct.unpack_from('<I', cpu_blob, i*4)[0]
    out['EIP']    = struct.unpack_from('<I', cpu_blob, 0x20)[0]
    out['EFLAGS'] = struct.unpack_from('<Q', cpu_blob, 0x28)[0] & 0xFFFFFFFF
    SEGS = 0xEB
    for i, name in enumerate(['ES','CS','SS','DS','FS','GS']):
        out[name] = struct.unpack_from('<Q', cpu_blob, SEGS + i*8)[0] & 0xFFFF
    return out

if __name__ == '__main__':
    sav = sys.argv[1] if len(sys.argv) > 1 else 'tools/dosbox/save/1.sav'
    z = zipfile.ZipFile(sav)
    cpu = z.read('CPU')
    r = decode_cpu_registers(cpu)
    for k, v in r.items():
        print(f'  {k:6} = 0x{v:08x}')
